30	constexpr int64_t kDefaultAxisId = -1;
31	constexpr int64_t kMaxBroadcastAxisSize = 16LL;
32	constexpr int64_t kMinNonBroadcastAxisSize = 256LL * 1024LL;
33	
34	void FindNotLoopAxis(const ascir::NodeView &node, ascir::ImplGraph &impl_graph,
35	                     std::unordered_set<int64_t> &not_loop_axis_set, bool has_reduce, bool is_reduce_first_stage) {
36	  for (auto output : node->outputs()) {
37	    not_loop_axis_set.insert(output->attr.vectorized_axis.begin(), output->attr.vectorized_axis.end());
38	  }
39	  if (!has_reduce) {
40	    return;
41	  }
42	  af::AxisPtr block_axis = nullptr;
43	  for (const auto &axis : impl_graph.GetAllAxis()) {
44	    if (axis != nullptr && axis->type == ascir::Axis::Type::kAxisTypeBlockOuter) {
45	      block_axis = axis;
46	      break;
47	    }
48	  }
49	  // find reduce axis of input
50	  for (auto input : node->inputs()) {
51	    for (size_t i = 0; i < input->attr.repeats.size(); i++) {
52	      if ((af::SymbolicUtils::StaticCheckEq(input->attr.repeats[i], af::sym::kSymbolOne) != af::TriBool::kTrue) ||
53	          (af::SymbolicUtils::StaticCheckEq(input->attr.strides[i], af::sym::kSymbolZero) != af::TriBool::kTrue)) {
54	        continue;
55	      }
56	      auto r = impl_graph.FindAxis(input->attr.axis[i]);
57	      if (r == nullptr) {
58	        continue;
59	      }
60	      if (is_reduce_first_stage) {
61	        if (block_axis != nullptr &&
62	            std::find(block_axis->from.begin(), block_axis->from.end(), r->id) != block_axis->from.end()) {
63	          continue;
64	        }
65	      } else {
66	        if (r->type == ascir::Axis::Type::kAxisTypeBlockOuter || r->type == ascir::Axis::Type::kAxisTypeBlockInner) {
67	          continue;
68	        }
69	      }
70	      not_loop_axis_set.insert(input->attr.axis[i]);
71	    }
72	  }
73	}
74	
75	bool IsNotLoopAxis(ascir::ImplGraph &impl_graph, int64_t axis, const std::unordered_set<int64_t> &not_loop_axis_set) {
76	  if (not_loop_axis_set.find(axis) != not_loop_axis_set.end()) {
77	    return true;
78	  }
79	  auto r = impl_graph.FindAxis(axis);
80	  if (r == nullptr) {
81	    return false;
82	  }
83	  if (r->from.empty()) {
84	    return false;
85	  }
86	  for (auto c : r->from) {
87	    if (!IsNotLoopAxis(impl_graph, c, not_loop_axis_set)) {
88	      return false;
89	    }
90	  }
91	  return true;
92	}
93	
94	int64_t GetStaticAxisProduct(ascir::ImplGraph &impl_graph, const std::vector<int64_t> &axis_ids) {
95	  int64_t product = 1;
96	  for (const auto axis_id : axis_ids) {
97	    auto axis = impl_graph.FindAxis(axis_id);
98	    if (axis == nullptr || !axis->size.IsConstExpr()) {
99	      return -1;
100	    }
101	    int64_t static_size = 0;
102	    if (!axis->size.GetConstValue(static_size) || static_size <= 0) {
103	      return -1;
104	    }
105	    product *= static_size;
106	  }
107	  return product;
108	}
109	
110	std::unordered_set<int64_t> CollectBroadcastAxes(const ascir::ImplGraph &impl_graph) {
111	  std::unordered_set<int64_t> broadcast_axes;
112	  for (const auto &node : impl_graph.GetAllNodes()) {
113	    if (!optimize::ScheduleUtils::IsLoad(node)) {
114	      continue;
115	    }
116	    const auto &output = node->outputs[0];
117	    for (size_t i = 0; i < output.attr.axis.size(); ++i) {
118	      if (af::SymbolicUtils::StaticCheckEq(output.attr.strides[i], af::sym::kSymbolZero) == af::TriBool::kTrue) {
119	        broadcast_axes.insert(output.attr.axis[i]);
120	      }
121	    }
122	  }
123	  return broadcast_axes;
124	}
125	
126	void PartitionLoopAxes(const ascir::ImplGraph &impl_graph, const std::unordered_set<int64_t> &broadcast_axes,
127	                       std::vector<int64_t> &new_order, std::vector<int64_t> &brc_axes) {
128	  for (const auto &node : impl_graph.GetAllNodes()) {
129	    if (!optimize::ScheduleUtils::IsBuffer(node)) {
130	      new_order.reserve(node->attr.sched.axis.size());
131	      for (const auto axis_id : node->attr.sched.axis) {
132	        if (broadcast_axes.count(axis_id) > 0) {
133	          brc_axes.push_back(axis_id);
134	        } else {
135	          new_order.push_back(axis_id);
136	        }
137	      }
138	      break;
139	    }
140	  }
141	}
142	
143	void ReorderBroadcastAxesInner(ascir::ImplGraph &impl_graph) {
144	  optimize::GraphPropertiesCache cache(impl_graph);
145	  if (cache.HasReduce() || cache.HasGather() || cache.HasCube() || cache.HasTranspose() || cache.HasConcat() ||
146	      cache.HasSplit()) {
147	    return;
148	  }
149	  auto broadcast_axes = CollectBroadcastAxes(impl_graph);
150	  if (broadcast_axes.empty()) {
151	    return;
152	  }
153	  std::vector<int64_t> new_order;
154	  std::vector<int64_t> brc_axes;
155	  PartitionLoopAxes(impl_graph, broadcast_axes, new_order, brc_axes);
156	  if (brc_axes.empty() || new_order.empty() || new_order.size() + brc_axes.size() > 2UL) {
157	    return;
158	  }
159	
160	  int64_t brc_size = GetStaticAxisProduct(impl_graph, brc_axes);
161	  if (brc_size <= 0 || brc_size > kMaxBroadcastAxisSize) {
162	    GELOGD("Skip broadcast reorder: brc_size=%ld.", brc_size);
163	    return;
164	  }
165	  int64_t non_brc_size = GetStaticAxisProduct(impl_graph, new_order);
166	  if (non_brc_size <= 0 || non_brc_size <= kMinNonBroadcastAxisSize) {
167	    return;
168	  }
169	  new_order.insert(new_order.end(), brc_axes.begin(), brc_axes.end());
170	  for (const auto &node : impl_graph.GetAllNodes()) {
171	    if (!optimize::ScheduleUtils::IsBuffer(node)) {
172	      node->attr.sched.axis = new_order;
173	    }
174	  }
175	  GELOGI("Broadcast reorder: brc_size=%ld, non_brc_size=%ld, graph=[%s]", brc_size, non_brc_size,
176	         impl_graph.GetName().c_str());
177	}
