185	// Returns true if an IndirectLoad prebuilt tiling case was generated, and the caller should return early.
186	bool TryGenIndirectLoadTilingCase(ascir::ImplGraph &graph,
187	                                  std::vector<optimize::autoschedule::TilingCase> &tiling_cases) {
188	  optimize::autoschedule::TilingCase tiling_case;
189	  if (!ascgen_utils::indirect_load::GetPrebuiltYTilingCase(graph, tiling_case.ub_tiling_id_y,
190	                                                           tiling_case.ub_tiling_y)) {
191	    return false;
192	  }
193	  if (tiling_case.ub_tiling_y.first != nullptr && tiling_case.ub_tiling_y.second != nullptr) {
194	    tiling_case.block_tiling_id = 0;
195	    tiling_cases.push_back(tiling_case);
196	    GELOGD("[IndirectLoad] Graph[%s] generate prebuilt outer tiling case for axis[%ld].", graph.GetName().c_str(),
197	           tiling_case.ub_tiling_id_y);
198	  }
199	  return true;
200	}
