204	Status AutoSchedule::SelectLoopAxis(ascir::ImplGraph &impl_graph, bool is_reduce_fullload) const {
205	  bool has_reduce = false;
206	  for (auto node : impl_graph.GetAllNodes()) {
207	    GE_ASSERT_NOTNULL(node);
208	    node->attr.sched.loop_axis = af::kIdNone;
209	    if (node->attr.api.type != af::ApiType::kAPITypeCompute ||
210	        ascgen_utils::indirect_load::GetTemplateBehavior(node).skips_main_schedule_tiling) {
211	      continue;
212	    }
213	    if (ScheduleUtils::IsReduce(node) && !is_reduce_fullload) {
214	      has_reduce = true;
215	    }
216	    auto axis = node->attr.sched.axis;
217	    std::unordered_set<int64_t> not_loop_axis_set;
218	    FindNotLoopAxis(node, impl_graph, not_loop_axis_set, has_reduce, is_reduce_first_stage_);
219	    for (auto &s : axis) {
220	      if (IsNotLoopAxis(impl_graph, s, not_loop_axis_set)) {
221	        s = af::kIdNone;
222	        continue;
223	      }
224	    }
225	
226	    auto it = std::find_if(axis.rbegin(), axis.rend(), [](const auto &val) { return val != af::kIdNone; });
227	    if (it != axis.rend()) {
228	      node->attr.sched.loop_axis = *it;
229	    }
230	    GE_ASSERT_TRUE((node->attr.sched.loop_axis != af::kIdNone), "Cannot find loop axis for node: [%s].",
231	                   node->GetNamePtr());
232	  }
233	  return af::SUCCESS;
234	}
235	
236	void AutoSchedule::GenTilingCase(std::vector<TilingCase> &tiling_cases) {
237	  auto set_tiling_id = [](auto &field, auto tid) {
238	    if (tid != kDefaultAxisId) {
239	      field = tid;
240	    }
241	  };
242	
243	  if (TryGenIndirectLoadTilingCase(graph_, tiling_cases)) {
244	    return;
245	  }
246	
247	  if (cube_template_ != ascir::CubeTemplateType::kDefault) {
248	    for (const auto &y_id : axes_group_.y_group) {
249	      TilingCase tiling_case;
250	      set_tiling_id(tiling_case.ub_tiling_id_y, y_id);
251	      tiling_cases.push_back(tiling_case);
252	    }
253	    return;
254	  }
255	  auto append_reduce_case = [&tiling_cases](const TilingCase &base_case) {
256	    auto reduce_case = base_case;
257	    reduce_case.block_tiling_id = 1;
258	    reduce_case.reduce_is_block = true;
259	    tiling_cases.push_back(reduce_case);
260	  };
261	
262	  int64_t attr_axis = -1L;
263	  int64_t params_size = -1L;
264	  bool has_gather = ScheduleUtils::GetGatherParams(graph_, attr_axis, params_size);
265	  if (has_gather && !(attr_axis == params_size - 1 && attr_axis == 0)) {
266	    int64_t cnt = 0;
267	    for (const auto &y_id : axes_group_.y_group) {
268	      if (++cnt == 1) {
269	        continue;
270	      }
271	      TilingCase tiling_case;
272	      set_tiling_id(tiling_case.ub_tiling_id_y, y_id);
273	      tiling_case.block_tiling_id = 0;
274	      tiling_cases.push_back(tiling_case);
275	    }
276	    return;
277	  }
278	
279	  // 生成通用pattern
280	  // 遍历所有的group，分别从每个group中取出1个值，组成所有的tiling case
281	  for (const auto &x_id : axes_group_.x_group) {
282	    for (const auto &y_id : axes_group_.y_group) {
283	      for (const auto &r_id : axes_group_.r_group) {
284	        TilingCase tiling_case;
285	        set_tiling_id(tiling_case.ub_tiling_id_x, x_id);
286	        set_tiling_id(tiling_case.ub_tiling_id_y, y_id);
287	        set_tiling_id(tiling_case.ub_tiling_id_r, r_id);
288	        tiling_case.block_tiling_id = 0;
289	        if (is_reduce_first_stage_ && r_id != kDefaultAxisId) {
290	          append_reduce_case(tiling_case);
291	        } else {
292	          tiling_cases.push_back(tiling_case);
293	        }
294	      }
295	    }
296	  }
297	}
298	
299	// 尽量不生成切size=1轴的tiling case
300	Status AutoSchedule::PruneTilingCase(std::vector<TilingCase> &tiling_cases) const {
301	  auto all_axis = graph_.GetAllAxis();
302	  for (auto it = tiling_cases.begin(); it != tiling_cases.end();) {
303	    // 仅处理单切分场景
304	    if ((it->ub_tiling_id_r != kDefaultAxisId) || (it->ub_tiling_id_x != kDefaultAxisId)) {
305	      ++it;
306	      continue;
307	    }
308	
309	    auto axis = graph_.FindAxis(it->ub_tiling_id_y);
310	    GE_ASSERT_NOTNULL(axis, "Tiling case is invalid axis_id:[%ld].", it->ub_tiling_id_y);
311	    if (af::SymbolicUtils::StaticCheckEq(axis->size, af::sym::kSymbolOne) == af::TriBool::kTrue &&
312	        tiling_cases.size() > 1UL) {
313	      it = tiling_cases.erase(it);
314	      GELOGD("Axis [%s]'s size is 1, will skip cutting it.", axis->name.c_str());
315	    } else {
316	      ++it;
317	    }
318	  }
319	  return af::SUCCESS;
320	}
321	
322	static std::string GetTilingCaseStr(const std::string &graph_name, const TilingCase &tiling_case) {
323	  std::stringstream ss;
324	  ss << graph_name << "_";
325	  AppendIdIfNotDefault(ss, "B", tiling_case.block_tiling_id);
326	  AppendIdIfNotDefault(ss, "X", tiling_case.ub_tiling_id_x);
327	  AppendIdIfNotDefault(ss, "Y", tiling_case.ub_tiling_id_y);
328	  AppendIdIfNotDefault(ss, "R", tiling_case.ub_tiling_id_r);
329	  return ss.str();
330	}
331	
332	Status BuildIndirectLoadAxisGroup(const ascir::ImplGraph &graph, const AxisGroup &base_group, AxisGroup &axis_group) {
333	  const af::AscNodePtr indirect_load = ascgen_utils::indirect_load::FindIndirectLoadNode(graph);
334	  if (indirect_load == nullptr) {
335	    axis_group = base_group;
336	    return af::SUCCESS;
337	  }
338	
339	  ascgen_utils::indirect_load::TemplateAxes axes;
340	  GE_ASSERT_SUCCESS(ascgen_utils::indirect_load::GetTemplateAxes(indirect_load, axes));
341	  axis_group = {};
342	  axis_group.y_group.push_back(axes.outer_axis);
343	  axis_group.axes_order.resize(axis_group.y_group.size());
344	  std::iota(axis_group.axes_order.begin(), axis_group.axes_order.end(), 0UL);
345	  GELOGD("[IndirectLoad] Graph[%s] use template axis group[%s].", graph.GetName().c_str(),
346	         axis_group.ToString().c_str());
347	  return af::SUCCESS;
348	}
349	
350	Status AutoSchedule::DoAutoSchedule() {
351	  graph_.SetGraphType(af::AscGraphType::kImplGraph);
352	  ReorderBroadcastAxesInner(graph_);
353	
354	  // 生成通用模版
355	  std::vector<TilingCase> tiling_cases;
356	  GE_CHK_STATUS_RET(PrepareTilingCases(tiling_cases), "Failed to prepare tiling cases for graph: [%s]",
357	                    graph_.GetName().c_str());
358	
359	  const bool is_last_axis_reduce = ScheduleUtils::IsLastAxisReduce(graph_);
360	  const bool is_reduce_full_load = (reduce_template_ == optimize::ReduceTemplateType::kAllLoad);
361	  for (size_t index = 0UL; index < tiling_cases.size(); ++index) {
362	    GE_CHK_STATUS_RET(ProcessOneTilingCase(tiling_cases[index], index, is_last_axis_reduce, is_reduce_full_load),
363	                      "Failed to process tiling case %zu for graph: [%s]", index, graph_.GetName().c_str());
364	  }
365	
366	  // 生成多模板
367	  GE_CHK_STATUS_RET(TemplateGeneratorHandler::GenerateTemplates(graph_, schd_outputs_),
368	                    "Failed to generate templates for graph: [%s]", graph_.GetName().c_str());
369	
370	  // 生成 UBFuse 模板 TTODO待归到多模版内
371	  if (cube_template_ == ascir::CubeTemplateType::kUBFuse) {
372	    GenUBFuseTemplates();
373	  }
374	
375	  return af::SUCCESS;
376	}
377	
378	Status AutoSchedule::PrepareTilingCases(std::vector<TilingCase> &tiling_cases) {
379	  const bool is_reduce_full_load = (reduce_template_ == optimize::ReduceTemplateType::kAllLoad);
380	  GE_CHK_STATUS_RET(TilingGroup::GenTilingGroup(graph_, axes_group_, is_reduce_full_load),
381	                    "Gen tiling group failed for graph: [%s]", graph_.GetName().c_str());
382	  TilingGroup::NormGroup(axes_group_);
383	
384	  GenTilingCase(tiling_cases);
385	  GE_CHK_STATUS_RET(PruneTilingCase(tiling_cases), "Failed to prune tiling cases for graph: [%s]",
386	                    graph_.GetName().c_str());
387	
388	  GE_ASSERT_TRUE(!tiling_cases.empty(), "No valid tiling cases for graph: [%s]. Please check graph legality.",
389	                 graph_.GetName().c_str());
390	
391	  return af::SUCCESS;
392	}
393	
394	Status AutoSchedule::ProcessOneTilingCase(TilingCase &tiling_case, size_t index, bool is_last_axis_reduce,
395	                                          bool is_reduce_full_load) const {
396	  const std::string graph_name = GetTilingCaseStr(ascgen_utils::GenValidName(graph_.GetName()), tiling_case);
397	  AutoScheduleOutput output(graph_name.c_str());
398	  GE_ASSERT_TRUE(output.scheduled_graph.CopyFrom(graph_), "Failed to copy graph for tiling case %zu in graph: [%s]",
399	                 index, graph_.GetName().c_str());
400	
401	  AxisGroup axis_group;
402	  GE_CHK_STATUS_RET(BuildIndirectLoadAxisGroup(output.scheduled_graph, axes_group_, axis_group),
403	                    "Failed to build scheduler axis group for tiling case %zu in graph: [%s]", index,
404	                    graph_name.c_str());
405	  Scheduler scheduler(output.scheduled_graph, axis_group, tiling_case, is_last_axis_reduce, reduce_template_,
406	                      cube_template_);
407	
408	  auto ret = scheduler.DoScheduler();
409	  if (ret == af::UNSUPPORTED) {
410	    GELOGW("Tiling case %zu (graph: [%s]) is unsupported, skip it.", index, graph_name.c_str());
411	    return af::SUCCESS;
412	  }
413	  GE_CHK_STATUS_RET(ret, "Scheduler failed for tiling case %zu in graph: [%s]", index, graph_name.c_str());
414	
415	  if (tiling_case.reduce_is_block) {
416	    GE_ASSERT_TRUE(
417	        output.scheduled_graph.BindBlock(tiling_case.block_tiling_id, tiling_case.reduce_block_tiling.second->id));
418	    output.var_relations_["Rm_org_size"] = tiling_case.rm_org_size;
419	    output.var_relations_["A_org_size"] = tiling_case.a_org_size;
420	  }
421	
422	  GE_CHK_STATUS_RET(SelectLoopAxis(output.scheduled_graph, is_reduce_full_load),
423	                    "Failed to select loop axis for tiling case %zu in graph: [%s]", index, graph_name.c_str());
424	
425	  schd_outputs_.emplace_back(output);
426	  return af::SUCCESS;
427	}
428	
429	void AutoSchedule::GenUBFuseTemplates() const {
430	  std::vector<AutoScheduleOutput> schd_outputs_non_db;
431	  schd_outputs_non_db.reserve(schd_outputs_.size());
432	  for (const auto &schd_output : schd_outputs_) {
433	    auto graph_name = schd_output.scheduled_graph.GetName() + "_non_db";
434	    AutoScheduleOutput output_non_db(graph_name.c_str());
435	    output_non_db.scheduled_graph.CopyFrom(schd_output.scheduled_graph);
436	    output_non_db.var_relations_ = schd_output.var_relations_;
437	    output_non_db.score_func = schd_output.score_func;
438	    schd_outputs_non_db.emplace_back(std::move(output_non_db));
439	  }
440	  schd_outputs_.insert(schd_outputs_.begin(), std::make_move_iterator(schd_outputs_non_db.begin()),
441	                       std::make_move_iterator(schd_outputs_non_db.end()));
442	}
443	}  // namespace optimize::autoschedule
