20	bool CompareByOrderInTensorAxis(const int64_t &lhs, const int64_t &rhs, const std::vector<int64_t> &tensor_axes) {
21	  auto iter_lhs = std::find(tensor_axes.begin(), tensor_axes.end(), lhs);
22	  auto iter_rhs = std::find(tensor_axes.begin(), tensor_axes.end(), rhs);
23	  return iter_lhs < iter_rhs;
24	}
25	
26	bool IsAxisConsumedByReduce(const af::AscNodePtr &node, const int64_t axis_id) {
27	  const auto &brc_out_attr = node->outputs[0].attr;
28	  if (brc_out_attr.axis.size() != brc_out_attr.repeats.size()) {
29	    return false;
30	  }
31	  auto brc_axis_iter = std::find(brc_out_attr.axis.begin(), brc_out_attr.axis.end(), axis_id);
32	  if (brc_axis_iter == brc_out_attr.axis.end()) {
33	    return false;
34	  }
35	  const auto brc_idx = static_cast<size_t>(std::distance(brc_out_attr.axis.begin(), brc_axis_iter));
36	
37	  for (const auto &out_node : node->GetOutDataNodes()) {
38	    auto asc_out_node = std::dynamic_pointer_cast<af::AscNode>(out_node);
39	    if ((asc_out_node == nullptr) || !optimize::ScheduleUtils::IsReduce(asc_out_node)) {
40	      continue;
41	    }
42	    const auto &reduce_out_attr = asc_out_node->outputs[0].attr;
43	    if (reduce_out_attr.axis.size() != reduce_out_attr.repeats.size()) {
44	      continue;
45	    }
46	
47	    auto reduce_axis_iter = std::find(reduce_out_attr.axis.begin(), reduce_out_attr.axis.end(), axis_id);
48	    if (reduce_axis_iter == reduce_out_attr.axis.end()) {
49	      continue;
50	    }
51	    const auto reduce_idx = static_cast<size_t>(std::distance(reduce_out_attr.axis.begin(), reduce_axis_iter));
52	    const bool is_axis_consumed =
53	        af::SymbolicUtils::StaticCheckEq(brc_out_attr.repeats[brc_idx], reduce_out_attr.repeats[reduce_idx]) !=
54	        af::TriBool::kTrue;
55	    if (is_axis_consumed) {
56	      return true;
57	    }
58	  }
59	  return false;
60	}
61	
62	bool HasBroadcastExpansionOnNonVectorizedAxis(const af::AscNodePtr &brc_node, const af::AscTensorAttr &input_attr,
63	                                              const af::AscTensorAttr &output_attr) {
64	  if ((input_attr.axis.size() != input_attr.repeats.size()) ||
65	      (output_attr.axis.size() != output_attr.repeats.size())) {
66	    return false;
67	  }
68	
69	  for (size_t idx = 0UL; idx < output_attr.axis.size(); ++idx) {
70	    const auto axis_id = output_attr.axis[idx];
71	    if (std::find(output_attr.vectorized_axis.begin(), output_attr.vectorized_axis.end(), axis_id) !=
72	        output_attr.vectorized_axis.end()) {
73	      continue;
74	    }
75	
76	    auto input_axis_iter = std::find(input_attr.axis.begin(), input_attr.axis.end(), axis_id);
77	    if (input_axis_iter == input_attr.axis.end()) {
78	      continue;
79	    }
80	    const auto input_idx = static_cast<size_t>(std::distance(input_attr.axis.begin(), input_axis_iter));
81	    const bool is_broadcast_expanded =
82	        af::SymbolicUtils::StaticCheckEq(output_attr.repeats[idx], input_attr.repeats[input_idx]) != af::TriBool::kTrue;
83	    if (is_broadcast_expanded && IsAxisConsumedByReduce(brc_node, axis_id)) {
84	      return true;
85	    }
86	  }
87	  return false;
88	}
89	
90	bool IsRedundantBroadcast(const ascir::ImplGraph &impl_graph, const af::AscNodePtr &brc_node,
91	                          const af::AscNodePtr &pre_node, const uint32_t pre_node_out_index) {
92	  if (optimize::ScheduleUtils::IsIOBuffer(pre_node)) {
93	    return false;
94	  }
95	  std::vector<af::Expression> in_vec_repeats;
96	  const auto &in_attr = pre_node->outputs[pre_node_out_index].attr;
97	  GE_WARN_ASSERT(optimize::ScheduleUtils::GetVectorRepeats(in_attr.repeats, in_attr.axis, in_attr.vectorized_axis,
98	                                                           in_vec_repeats) == af::SUCCESS,
99	                 "%s[%s] GetVectorRepeats failed", pre_node->GetTypePtr(), pre_node->GetNamePtr());
100	  std::vector<af::Expression> out_vec_repeats;
101	  GE_WARN_ASSERT(optimize::ScheduleUtils::GetNodeOutVectorRepeats(brc_node, out_vec_repeats) == af::SUCCESS);
102	
103	  if (out_vec_repeats.size() != in_vec_repeats.size()) {
104	    GELOGD("Graph [%s] Broadcast [%s] output vector strides.size(%zu) != in vector strides.size(%zu), skip it",
105	           impl_graph.GetName().c_str(), brc_node->GetNamePtr(), out_vec_repeats.size(), in_vec_repeats.size());
106	    return false;
107	  }
108	  for (size_t idx = 0; idx < out_vec_repeats.size(); idx++) {
109	    if (af::SymbolicUtils::StaticCheckEq(out_vec_repeats[idx], in_vec_repeats[idx]) != af::TriBool::kTrue) {
110	      return false;
111	    }
112	  }
113	
114	  const auto &out_attr = brc_node->outputs[0].attr;
115	  if (!optimize::ScheduleUtils::IsBroadcast(pre_node) &&
116	      HasBroadcastExpansionOnNonVectorizedAxis(brc_node, in_attr, out_attr)) {
117	    GELOGD("Graph [%s] Broadcast [%s] has valid non-vectorized shape expansion, keep it.", impl_graph.GetName().c_str(),
118	           brc_node->GetNamePtr());
119	    return false;
120	  }

