static bool CalculateRAxisTotalSize(const af::AscTensorAttr &input_attr, const af::AscTensorAttr &output_attr,
                                    int64_t &r_axis_total_size, int64_t &a_axis_total_size, const char *node_name) {
  r_axis_total_size = 1;
